export function commandsFor(context){return COMMAND_REGISTRY.filter(c=>c.context===context)}
export function commandFor(context,input){const u=input.trim().toUpperCase();const list=commandsFor(context);return list.find(c=>c.key===u||c.aliases.includes(u)||c.key==='#'&&/^(?:#)?\d+$/.test(u)||c.key==='NN'&&context==='logon'||c.key==='ATDT/ATDP'&&/^ATD[TP]\d+$/.test(u)||c.key==='ATE0/1'&&/^ATE[01]$/.test(u)||c.key==='ATV0/1'&&/^ATV[01]$/.test(u)||c.key==='ATQ0/1'&&/^ATQ[01]$/.test(u)||c.key==='ATS0?/=0/=1'&&/^ATS0(?:\?|=[01])$/.test(u)||c.key==='ATH/ATH0'&&/^ATH0?$/.test(u)||context==='message-editor'&&c.key==='/L'&&/^\/L\d*$/.test(u)||context==='message-editor'&&c.key==='/E'&&/^\/E\d*$/.test(u)||context==='message-editor'&&c.key==='/D'&&/^\/D\d*$/.test(u)||context==='message-editor'&&c.key==='/I'&&/^\/I\d*$/.test(u)||context==='multinode-chat'&&c.key==='/MSG'&&u.startsWith('/MSG ')||context==='multinode-chat'&&c.key==='/ME'&&u.startsWith('/ME ')||context==='file-transfer'&&c.key==='/#'&&/^\/\d+$/.test(u))}
export function numericResult(name,baud=2400){return ({OK:'0',CONNECT:baud===2400?'10':'1',RING:'2','NO CARRIER':'3',ERROR:'4','NO DIALTONE':'6',BUSY:'7','NO ANSWER':'8'})[name]??'4'}
export function modemResponse(rt,input){let u=input.trim().toUpperCase();if(u==='A/')u=rt.lastAT||'';else if(u.startsWith('AT'))rt.lastAT=u;if(u==='AT')return ['OK'];if(u==='ATZ'){Object.assign(rt,{echo:true,verbal:true,quiet:false,s0:0});return ['OK']}if(u==='ATI')return ['MIDNIGHT MR-144 FICTIONAL DATA MODEM','300 1200 2400 9600 14400 BIT/S','BROWSER SIMULATION — NO TELEPHONE CONNECTION','OK'];if(u==='AT&V')return [`E${+rt.echo} V${+rt.verbal} Q${+rt.quiet} S0=${rt.s0} SPEED=${rt.baud}`,'OK'];if(/^ATE[01]$/.test(u)){rt.echo=u.endsWith('1');return ['OK']}if(/^ATV[01]$/.test(u)){rt.verbal=u.endsWith('1');return ['OK']}if(/^ATQ[01]$/.test(u)){rt.quiet=u.endsWith('1');return ['OK']}if(u==='ATS0?')return [String(rt.s0),'OK'];if(/^ATS0=[01]$/.test(u)){rt.s0=+u.at(-1);return ['OK']}if(/^ATH0?$/.test(u)){rt.carrier=false;return ['NO CARRIER','OK']}if(u==='ATO'&&rt.carrier){rt.onlineCommand=false;return ['CONNECT']}if(/^ATD[TP]/.test(u)){const n=u.slice(4);if(n==='5550194'){rt.carrier=true;return ['CONNECT']}return [({'5550100':'BUSY','5550101':'NO ANSWER','5550102':'NO DIALTONE'})[n]||'NO CARRIER']}return ['ERROR']}

