export function museumFilePage(f){return `--------------------------------------------------\n${f.name}\n\nDeveloper:\n${f.developer}\n\nRelease:\n${f.release}\n\nDescription:\n${f.description}\n\nWhy it became popular:\n${f.popular}\n\nTypical BBS distribution:\n${f.distribution}\n\nMuseum note:\n${f.museumNote}\n--------------------------------------------------`}
export function museumNfoPage(f){if(!f.nfo)return 'No README.NFO is cataloged for this entry.';return `+------------------------------------------------+\n|                  README.NFO                    |\n+------------------------------------------------+\n${f.nfo}\n\nHISTORICAL REFERENCE ONLY — NO SOFTWARE INCLUDED\n+------------------------------------------------+`}
export function wildcardToRegExp(pattern){const safe=String(pattern||'*').toUpperCase().replace(/([.+^${}()|[\]\\])/g,'\\$1').replace(/\*/g,'.*').replace(/\?/g,'.');return new RegExp(`^${safe}$`)}
export function searchFiles(query='*',scope='all',lib=0,dir=0,description=false,libraries=FILE_LIBRARIES){const rx=description?null:wildcardToRegExp(query),needle=String(query).toLowerCase(),out=[];libraries.forEach((l,li)=>l.directories.forEach((d,di)=>{if(scope==='directory'&&(li!==lib||di!==dir)||scope==='library'&&li!==lib)return;d.files.forEach(f=>{if(description?f.description.toLowerCase().includes(needle):rx.test(f.name))out.push({...f,library:li,directory:di})})}));return out}
export const PROTOCOLS={XMODEM:{batch:false,efficiency:.78,resume:false,block:128},YMODEM:{batch:true,efficiency:.82,resume:false,block:1024},ZMODEM:{batch:true,efficiency:.92,resume:true,block:0},'YMODEM-G':{batch:true,efficiency:.94,resume:false,block:1024,reliable:true}};
