export function runNightlyExchange(store,account='GUEST'){store.networkReceived??=[];store.mailerLogs??=[];store.outboundNetmail??=[];const marker='nightly-1994-09-19';if(!store.networkReceived.some(m=>m.exchange===marker)){const incoming={id:9001,group:2,sub:0,from:'HarborMaster',to:'ALL',subject:'Unix Harbor nightly hello',date:'1994-09-19 03:14',private:false,origin:'SIMULATED NETWORK ORIGIN 2:2490/121',receivedDuring:'nightly exchange',exchange:marker,seeded:false,body:'A deterministic store-and-forward greeting from fictional Unix Harbor.'};store.networkReceived.push(incoming);store.posts.push(incoming)}const sent=store.outboundNetmail.length;store.outboundNetmail=[];const lines=['Scanning outbound mail',`Packing MIDNIGHT-MAIL-BUNDLE.TXT (${sent} message(s))`,'Dialing fictional node 2:2490/42','Handshake / carrier established','Sending outbound text bundle','Receiving inbound text bundle','Unpacking messages','Updating message bases','Writing MAILER.LOG','Hanging up'];store.mailerLogs.push({date:'1994-09-19 03:14',account,lines});store.mailerLogs=store.mailerLogs.slice(-20);return lines}

